import { Field } from '../../docx/DocModel';
import { CheckBase, CheckKind } from '../Check';
import { isSameValue } from '../properties';
import { groupBy } from './helpers';

type DirectoryType = 'tableOfContents' | 'tableOfFigures' | 'bibliography';

/** The document contains a directory generated by Word, e.g. the table of contents. */
export interface FieldCheck extends CheckBase<'field'> {
    expect: {
        type: DirectoryType;
        /** Caption label of a table of figures, e.g. `Abbildung`. */
        label?: string;
        /** Heading levels of a table of contents, e.g. `1-3`. */
        levels?: string;
    };
}

const DIRECTORY_TYPES: DirectoryType[] = ['tableOfContents', 'tableOfFigures', 'bibliography'];
const TYPE_LABELS: { [type in DirectoryType]: string } = {
    tableOfContents: 'Inhaltsverzeichnis',
    tableOfFigures: 'Abbildungsverzeichnis',
    bibliography: 'Literaturverzeichnis'
};

export const field: CheckKind<FieldCheck> = {
    category: 'Verzeichnisse',
    anchors: 'none',

    extract: ({ original }) => {
        const expectations = original.fields.flatMap((fieldOfOriginal) => {
            const expect = expectationOf(fieldOfOriginal);
            return expect ? [expect] : [];
        });
        return groupBy(expectations, (expect) => JSON.stringify(expect)).map(([expect]) => ({
            kind: 'field',
            title: describe(expect),
            expect
        }));
    },

    evaluate: (check, context) => {
        const candidates = context.document.fields
            .map(expectationOf)
            .filter((expect) => expect?.type === check.expect.type);
        if (candidates.some((candidate) => isSameValue(candidate, check.expect))) {
            return [];
        }
        if (candidates.length > 0) {
            return [`${describe(candidates[0]!)} statt ${describe(check.expect)}`];
        }
        return [`${TYPE_LABELS[check.expect.type]} fehlt`];
    }
};

const expectationOf = (fieldOfDocument: Field): FieldCheck['expect'] | undefined => {
    const type = DIRECTORY_TYPES.find((directoryType) => directoryType === fieldOfDocument.type);
    if (!type) {
        return undefined;
    }
    return {
        type,
        ...(fieldOfDocument.label ? { label: fieldOfDocument.label } : {}),
        ...(fieldOfDocument.levels ? { levels: fieldOfDocument.levels } : {})
    };
};

const describe = (expect: FieldCheck['expect']) => {
    const details = [expect.label, expect.levels && `Ebenen ${expect.levels}`].filter(Boolean);
    return `${TYPE_LABELS[expect.type]}${details.length > 0 ? ` (${details.join(', ')})` : ''}`;
};
